<?php
namespace App\Http\Controllers; use App\Models\PracticumClass; use Illuminate\Http\Request; class LecturerController extends Controller { public function dashboard(Request $r){ $classes=PracticumClass::with(['course','laboratory'])->withCount(['finalRegistrations'=>fn($q)=>$q->where('status','approved')])->where('lecturer_id',$r->user()->id)->get(); return view('dosen.dashboard',compact('classes')); } public function students(Request $r,PracticumClass $class){ abort_unless($class->lecturer_id===$r->user()->id,403); $class->load(['course','laboratory','finalRegistrations'=>fn($q)=>$q->where('status','approved')->with('student')]); return view('dosen.students',compact('class')); } }
